func (os SetSlice) Exercise(mods ...bob.Mod[*dialect.SelectQuery]) ExercisesQuery {
	pkExerciseID := make(pgtypes.Array[uuid.UUID], 0, len(os))

	// the array is only a filter (semi-join), so duplicate keys can be
	// dropped before they are sent over the wire
	seenExerciseID := make(map[uuid.UUID]struct{}, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		if _, ok := seenExerciseID[o.ExerciseID]; ok {
			continue
		}
		seenExerciseID[o.ExerciseID] = struct{}{}
		pkExerciseID = append(pkExerciseID, o.ExerciseID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkExerciseID), "uuid[]"))

	return Exercises.Query(append(mods,
		sm.Where(Exercises.Columns.ID.EQ(PKArgExpr)),
	)...)
}

