type setJoins[Q dialect.Joinable] struct {
	typ      string
	Exercise modAs[Q, exerciseColumns]
	Workout  modAs[Q, workoutColumns]
}

func (j setJoins[Q]) aliasedAs(alias string) setJoins[Q] {
	return buildSetJoins[Q](buildSetColumns(alias), j.typ)
}

func buildSetJoins[Q dialect.Joinable](cols setColumns, typ string) setJoins[Q] {
	return setJoins[Q]{
		typ: typ,
		Exercise: modAs[Q, exerciseColumns]{
			c: Exercises.Columns,
			f: func(to exerciseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Exercises.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ExerciseID),
					))
				}

				return mods
			},
		},
		Workout: modAs[Q, workoutColumns]{
			c: Workouts.Columns,
			f: func(to workoutColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Workouts.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.WorkoutID),
					))
				}

				return mods
			},
		},
	}
}
